import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.regex.Pattern;

public class DataSerializer {
    private static final ObjectMapper mapper = new ObjectMapper();
    private static final Pattern SAFE_FILENAME_PATTERN = Pattern.compile("^[a-zA-Z0-9_\\-]+\\.json$");
    private static final String BASE_DIR = "/var/data/exports";

    public boolean serializeToFile(String filename, Object data) throws IOException {
        // Line 17: Validate filename against strict whitelist pattern
        if (!SAFE_FILENAME_PATTERN.matcher(filename).matches()) {
            throw new IllegalArgumentException("Invalid filename format");
        }

        // Line 21: Resolve path and verify it stays within base directory
        Path targetPath = Paths.get(BASE_DIR, filename).normalize();
        if (!targetPath.startsWith(BASE_DIR)) {
            throw new SecurityException("Path traversal detected");
        }

        // Line 26: Serialize data to JSON string using Jackson (no OS command involved)
        String jsonContent = mapper.writeValueAsString(data);

        // Line 29: Write to file using Java NIO (no shell invocation)
        Files.write(targetPath, jsonContent.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        return true;
    }

    public static void main(String[] args) {
        DataSerializer serializer = new DataSerializer();
        try {
            // Example usage with user-controlled filename
            String userInput = "report_2024.json";
            serializer.serializeToFile(userInput, new java.util.HashMap<>());
            System.out.println("Serialization completed");
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}

// deploy.js - 自动化部署脚本，从配置文件读取目标服务器并执行部署命令
const fs = require('fs');
const path = require('path');
const { execFile } = require('child_process');

// 白名单：允许部署的目标服务器列表
const ALLOWED_TARGETS = new Set(['prod-web-01', 'prod-web-02', 'staging-api']);

function loadConfig(configPath) {
  const raw = fs.readFileSync(configPath, 'utf8');
  return JSON.parse(raw);
}

function validateTarget(target) {
  // 白名单校验：仅允许预定义的目标服务器
  if (!ALLOWED_TARGETS.has(target)) {
    throw new Error(`目标服务器 ${target} 不在白名单中`);
  }
  // 额外校验：禁止路径穿越或特殊字符
  if (!/^[a-zA-Z0-9\-_]+$/.test(target)) {
    throw new Error(`目标服务器名称包含非法字符: ${target}`);
  }
  return target;
}

function deploy(target, version) {
  const safeTarget = validateTarget(target);
  // 版本号也做严格校验，防止注入
  if (!/^\d+\.\d+\.\d+$/.test(version)) {
    throw new Error(`版本号格式不合法: ${version}`);
  }

  // 使用 execFile 而非 exec，参数以数组传递，不经过 shell 解释
  const scriptPath = path.join(__dirname, 'scripts', 'deploy.sh');
  const args = [safeTarget, version];

  return new Promise((resolve, reject) => {
    execFile(scriptPath, args, { timeout: 30000 }, (error, stdout, stderr) => {
      if (error) {
        reject(new Error(`部署失败: ${stderr || error.message}`));
      } else {
        console.log(`部署输出: ${stdout}`);
        resolve(stdout);
      }
    });
  });
}

async function main() {
  const config = loadConfig(path.join(__dirname, 'config', 'deploy-config.json'));
  // 从配置文件读取目标，但经过白名单校验
  const target = config.target;
  const version = config.version;

  try {
    await deploy(target, version);
    console.log(`成功部署 ${target} 版本 ${version}`);
  } catch (err) {
    console.error(`部署失败: ${err.message}`);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

# 运维脚本：容器镜像健康检查工具
# 功能：根据环境变量指定的容器名，执行 docker inspect 检查容器状态

import os
import subprocess
import json
import sys

# 允许检查的容器白名单（运维团队维护）
ALLOWED_CONTAINERS = {
    "nginx-gateway", "redis-cache", "postgres-db",
    "auth-service", "worker-pool"
}

def check_container_health(container_name: str) -> dict:
    """
    检查指定容器的健康状态
    使用白名单 + subprocess 列表参数双重防护
    """
    # 第一道防线：白名单校验
    # 阻断所有未列入白名单的容器名，包括路径穿越、命令注入等恶意输入
    if container_name not in ALLOWED_CONTAINERS:
        return {"error": f"Container '{container_name}' is not in allowed list"}

    # 第二道防线：subprocess 使用列表参数，不经过 shell 解析
    # 即使容器名包含特殊字符（如 ; | & $），也会被当作普通参数传递
    # shell=False 确保不会有命令注入的可能
    cmd = ["docker", "inspect", "--format", "{{.State.Health.Status}}", container_name]

    try:
        # shell=False 是默认值，显式声明以增强可读性
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=10,
            shell=False  # 关键：禁用 shell 解释，避免命令注入
        )

        if result.returncode == 0:
            status = result.stdout.strip()
            return {"container": container_name, "status": status}
        else:
            return {"error": f"Inspect failed: {result.stderr.strip()}"}

    except subprocess.TimeoutExpired:
        return {"error": "Health check timed out"}
    except Exception as e:
        return {"error": f"Unexpected error: {str(e)}"}

def main():
    # 从环境变量读取容器名（模拟 CI/CD 场景）
    container_name = os.environ.get("TARGET_CONTAINER", "")

    if not container_name:
        print("Error: TARGET_CONTAINER environment variable is required")
        sys.exit(1)

    result = check_container_health(container_name)
    print(json.dumps(result, indent=2))

    if "error" in result:
        sys.exit(1)

if __name__ == "__main__":
    main()

// docker-entrypoint.js
const { execFile } = require('child_process');
const fs = require('fs');
const path = require('path');

const ALLOWED_COMMANDS = new Set(['build', 'test', 'deploy']);

function validateCommand(command) {
  if (!ALLOWED_COMMANDS.has(command)) {
    throw new Error(`Command '${command}' not allowed`);
  }
  return command;
}

function runContainerCommand(command, args) {
  // 第8行：使用 execFile 而非 exec，强制列表参数传递
  return new Promise((resolve, reject) => {
    execFile(command, args, { shell: false }, (error, stdout, stderr) => {
      if (error) {
        reject(error);
        return;
      }
      resolve({ stdout, stderr });
    });
  });
}

async function main() {
  const args = process.argv.slice(2);

  // 第22行：解析入口参数，格式为 "command|arg1|arg2"
  if (args.length !== 1) {
    console.error('Usage: node entrypoint.js "command|arg1|arg2"');
    process.exit(1);
  }

  const parts = args[0].split('|');
  const command = parts[0];
  const commandArgs = parts.slice(1);

  // 第31行：白名单校验命令
  const safeCommand = validateCommand(command);

  // 第34行：参数清洗 - 移除空字符串和null字节
  const sanitizedArgs = commandArgs
    .filter(arg => arg && arg.length > 0)
    .map(arg => arg.replace(/\0/g, ''));

  // 第39行：执行命令，参数以数组形式传递
  const result = await runContainerCommand(safeCommand, sanitizedArgs);
  console.log(result.stdout);
}

main().catch(err => {
  console.error(`Execution failed: ${err.message}`);
  process.exit(1);
});

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import java.sql.*;

@Component
public class DatabaseConfig {
    @Value("${db.url}")
    private String dbUrl;
    @Value("${db.user}")
    private String dbUser;
    @Value("${db.password}")
    private String dbPassword;

    public Connection connect() throws SQLException {
        return DriverManager.getConnection(dbUrl, dbUser, dbPassword);
    }
}

import bcrypt

def hash_password(password):
    return bcrypt.hashpw(password.encode(), bcrypt.gensalt(rounds=12)).decode()

def check_password(password, hashed):
    return bcrypt.checkpw(password.encode(), hashed.encode())

